import {payrollMoney} from './payroll-contract.mjs';
export function createPayrollConfirmationViews({api,h,showPanel,localTime}){
 const action=a=>a==='confirm'?'确认并锁定':'重新开放修订';
 async function detail(id){await showPanel('工资确认版本',async signal=>{const r=await api.payrollConfirmationDetail(id,signal),s=r.snapshot,d=s?.draft;return `<div class="dialog-header"><h2>${h(r.month)} · 工资确认第 ${r.revision} 版</h2><button class="icon-button" data-attendance-close aria-label="关闭工资确认">×</button></div><p>${h(action(r.action))} · ${h(r.actor_name)} · ${h(localTime(r.created_at))}</p><p class="preserve-text">${h(r.note)}</p>${d?`<p class="planning-rule">这是当次锁定快照，是否仍为当前有效版本请返回工资页面核对。工资确认不表示实际支付。</p><h3>${h(s.member.name)}</h3><dl class="record-facts">${[['基础工资',d.base_cents],['奖金',d.bonus_cents],['补贴',d.allowance_cents],['其他调整',d.adjustment_cents],['确认合计',d.total_cents]].map(([k,v])=>`<div><dt>${h(k)}</dt><dd>${h(payrollMoney(v))}</dd></div>`).join('')}</dl><p class="preserve-text">金额依据：${h(d.note)}</p><p>引用草稿第 ${d.revision} 版 · 基础工资第 ${s.salary.revision} 版</p><button class="secondary" data-closure-detail="${h(s.closure.id)}">查看引用的考勤版本</button>`:'<p>工资已重新开放修订，此前确认金额保留在历史版本中。</p>'}${r.previous_id?`<button class="secondary" data-payroll-confirmation-detail="${h(r.previous_id)}">查看此前工资确认版本</button>`:''}`;});}
 async function history(month,memberId,offset=0){await showPanel('工资确认历史',async signal=>{const v=await api.payrollConfirmationHistory(month,memberId,offset,signal);return `<div class="dialog-header"><h2>${h(month)} · 工资确认历史</h2><button class="icon-button" data-attendance-close aria-label="关闭工资历史">×</button></div>${v.rows.map(r=>`<button class="asset-row" data-payroll-confirmation-detail="${h(r.id)}"><span><b>第 ${r.revision} 版 · ${h(action(r.action))}</b><small>${h(r.actor_name)} · ${h(localTime(r.created_at))}</small><small>${h(r.note)}</small></span><span>查看 ›</span></button>`).join('')||'<p>暂无工资确认记录。</p>'}<div class="pager"><button class="secondary" data-payroll-confirmation-history="${h(month)}" data-member="${h(memberId)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-payroll-confirmation-history="${h(month)}" data-member="${h(memberId)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 async function exports(month,offset=0){await showPanel('我的工资导出记录',async signal=>{const v=await api.payrollExportHistory(month,offset,signal);return `<div class="dialog-header"><h2>${h(month)} · 我的导出记录</h2><button class="icon-button" data-attendance-close aria-label="关闭导出历史">×</button></div><p class="planning-rule">以下是导出当时的快照文件，可能已有后续更正；重新核对后的当前版本请重新导出。</p>${v.rows.map(r=>`<article class="observation"><b>${h(localTime(r.created_at))}</b><p>${r.names.map(h).join('、')}</p><button class="secondary" data-payroll-export-file="${h(r.id)}" data-month="${h(month)}">下载当次历史文件</button></article>`).join('')||'<p>尚无本人导出记录。</p>'}<div class="pager"><button class="secondary" data-payroll-export-history="${h(month)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-payroll-export-history="${h(month)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 async function download(button){button.disabled=true;try{const f=await api.payrollExportFile(button.dataset.payrollExportFile),url=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=url;a.download=`Studio-OS-payroll-${button.dataset.month}-${f.id.slice(0,8)}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){await showPanel('历史文件读取失败',async()=>`<p>${h(e.message)}</p><button class="secondary" data-attendance-close>关闭</button>`);}finally{button.disabled=false;}}
 document.addEventListener('click',e=>{const d=e.target.closest('[data-payroll-confirmation-detail]'),hs=e.target.closest('[data-payroll-confirmation-history]');const ex=e.target.closest('[data-payroll-export-history]'),file=e.target.closest('[data-payroll-export-file]');if(ex)exports(ex.dataset.payrollExportHistory,Number(ex.dataset.offset||0));if(file)download(file);if(d)detail(d.dataset.payrollConfirmationDetail);if(hs)history(hs.dataset.payrollConfirmationHistory,hs.dataset.member,Number(hs.dataset.offset||0));});
 return {card(s,writable){if(!s.member)return '';const args=`data-month="${h(s.month)}" data-member="${h(s.member.id)}"`;return `<section class="planning-rule"><h3>${s.locked?(s.confirmationChanged?'工资已锁定，来源已有变化':'工资已确认锁定'):s.confirmation?'工资已重新开放，待确认':'工资尚未确认'}</h3><p>确认锁定后修改金额需先重新开放；历史金额与依据继续保留。工资确认与导出不代表实际支付。</p><div class="action-row">${writable?(s.locked?`<button class="secondary" data-payroll-operation="reopen" ${args}>说明原因并重新开放工资</button>`:`<button class="primary" data-payroll-operation="confirm" ${args} ${!s.draft||!s.attendanceValid||s.attendanceChanged||s.salaryChanged?'disabled':''}>确认并锁定工资</button>`):''}${s.confirmation?`<button class="secondary" data-payroll-confirmation-detail="${h(s.confirmation.id)}">查看最近确认版本</button>`:''}<button class="secondary" data-payroll-confirmation-history="${h(s.month)}" data-member="${h(s.member.id)}">工资确认历史</button>${writable?`<button class="secondary" data-payroll-operation="export" ${args}>选择本月工资并导出</button><button class="secondary" data-payroll-export-history="${h(s.month)}">我的导出记录</button>`:''}</div></section>`;}};
}
